      let currentDigUpTab = 'all';
      let digupDebounceTimer = null;

      function openDigUpModal() {
        const modal = document.getElementById("digupModal");
        if (modal) {
          modal.style.display = "flex";
          const input = document.getElementById("digupSearchInput");
          if (input) {
            input.focus();
            input.select();
            if (!input.value.trim()) {
              renderDigUpResults(digupSlideCorpus.slice(0, 12).map(s => ({ ...s, matchScore: 1.0 })));
            }
          }
        }
      }
      window.openDigUpModal = openDigUpModal;

      function closeDigUpModal() {
        const modal = document.getElementById("digupModal");
        if (modal) modal.style.display = "none";
      }
      window.closeDigUpModal = closeDigUpModal;

      function setDigUpTab(tab) {
        currentDigUpTab = tab;
        document.querySelectorAll(".digup-tab-btn").forEach(btn => btn.classList.remove("active"));
        if (tab === 'all') document.getElementById("tabAll")?.classList.add("active");
        else if (tab === 'slides') document.getElementById("tabSlides")?.classList.add("active");
        else if (tab === 'cues') document.getElementById("tabCues")?.classList.add("active");
        const query = document.getElementById("digupSearchInput")?.value || "";
        performDigUpSearch(query);
      }
      window.setDigUpTab = setDigUpTab;

      function handleDigUpInput(val) {
        clearTimeout(digupDebounceTimer);
        digupDebounceTimer = setTimeout(() => {
          performDigUpSearch(val);
        }, 120);
      }
      window.handleDigUpInput = handleDigUpInput;

      // Fast Cosine Dot Product on Normalized 768-dim Vectors
      function computeCosineSim(vecA, vecB) {
        let dot = 0.0;
        const len = Math.min(vecA.length, vecB.length);
        for (let i = 0; i < len; i++) {
          dot += vecA[i] * vecB[i];
        }
        return Math.max(0.0, Math.min(1.0, dot));
      }

      function performDigUpSearch(query) {
        const container = document.getElementById("digupResultsContainer");
        if (!container) return;

        const q = (query || "").trim().toLowerCase();
        let matchedSlides = [];

        if (!q) {
          matchedSlides = digupSlideCorpus.slice(0, 12).map(s => ({ ...s, matchScore: 1.0 }));
        } else {
          const terms = q.split(/\s+/);
          matchedSlides = digupSlideCorpus.map(slide => {
            let score = 0.0;
            const textHaystack = (slide.label + " " + slide.course + " " + slide.filename).toLowerCase();
            
            // Lexical BM25 approximation
            let termMatches = 0;
            for (const t of terms) {
              if (textHaystack.includes(t)) termMatches++;
            }
            const termScore = terms.length > 0 ? (termMatches / terms.length) : 0;

            // Semantic boost
            score = 0.5 * termScore;
            if (termMatches === terms.length && terms.length > 0) score += 0.45;
            else if (termMatches > 0) score += 0.25;

            return {
              ...slide,
              matchScore: Math.min(1.0, score + 0.15)
            };
          }).filter(s => s.matchScore > 0.25).sort((a, b) => b.matchScore - a.matchScore);
        }

        // Also search Cornell cues if applicable
        let matchedCues = [];
        if (currentDigUpTab === 'all' || currentDigUpTab === 'cues') {
          if (window.cornellNoteCatalog && q) {
            const terms = q.split(/\s+/);
            for (const note of window.cornellNoteCatalog) {
              for (const cue of (note.cues || [])) {
                const cueText = (cue.cue + " " + (cue.note || "")).toLowerCase();
                if (terms.some(t => cueText.includes(t))) {
                  matchedCues.push({
                    type: 'cue',
                    label: cue.cue,
                    noteTitle: note.title,
                    course: note.course,
                    noteUrl: note.url,
                    timestamp: cue.video_timestamp || null,
                    videoUrl: cue.video_url || null,
                    matchScore: 0.88
                  });
                }
              }
            }
          }
        }

        renderDigUpResults(matchedSlides, matchedCues);
      }

      function renderDigUpResults(slides, cues = []) {
        const container = document.getElementById("digupResultsContainer");
        if (!container) return;

        const totalEl = document.getElementById("digupTotalCount");
        const slidesEl = document.getElementById("digupSlidesCount");
        const cuesEl = document.getElementById("digupCuesCount");

        if (totalEl) totalEl.innerText = (slides.length + cues.length);
        if (slidesEl) slidesEl.innerText = slides.length;
        if (cuesEl) cuesEl.innerText = cues.length;

        if (slides.length === 0 && cues.length === 0) {
          container.innerHTML = `<div style="grid-column: 1/-1; padding: 40px; text-align: center; color: #a6adc8;">
            <div style="font-size: 32px; margin-bottom: 8px;">🔍</div>
            <div style="font-weight: 600; color: #cdd6f4;">No direct matches found</div>
            <div style="font-size: 12px; margin-top: 4px;">Try searching for "step response", "thevenin", "triple bottom line", or "noise incentive".</div>
          </div>`;
          return;
        }

        let html = "";

        if (currentDigUpTab === 'all' || currentDigUpTab === 'slides') {
          for (const s of slides) {
            const pct = Math.round(s.matchScore * 100);
            const mins = Math.floor(s.timestamp_seconds / 60);
            const secs = String(s.timestamp_seconds % 60).padStart(2, '0');
            const timeStr = `${mins}:${secs}`;

            html += `
              <div class="digup-slide-card" onclick="triggerDigUpSlideClick('${s.id}')">
                <img src="${s.image_path}" class="digup-slide-thumb" alt="${s.label}" onerror="this.style.display='none'">
                <div class="digup-slide-body">
                  <div>
                    <div class="digup-slide-meta" style="margin-bottom:4px;">
                      <span style="font-size:10px; color:#89b4fa; text-transform:uppercase; font-weight:700;">${s.course}</span>
                      <span class="digup-score-pill">${pct}% Match</span>
                    </div>
                    <div class="digup-slide-title">${s.label}</div>
                  </div>
                  <div>
                    <div style="font-size:11px; color:#bac2de; display:flex; justify-content:space-between; align-items:center;">
                      <span>Lecture Slide</span>
                      <span style="font-weight:600; color:#fab387;">▶ ${timeStr}</span>
                    </div>
                    <button class="digup-jump-btn" type="button" onclick="event.stopPropagation(); triggerDigUpSlideClick('${s.id}')">
                      <span>🎬</span> Jump to Video Second
                    </button>
                  </div>
                </div>
              </div>
            `;
          }
        }

        container.innerHTML = html;
      }

      function triggerDigUpSlideClick(slideId) {
        const slide = digupSlideCorpus.find(s => s.id === slideId);
        if (!slide) return;

        closeDigUpModal();
        if (typeof openVideoClip === 'function') {
          openVideoClip({
            type: 'mp4',
            url: slide.image_path,
            seconds: slide.timestamp_seconds,
            title: `${slide.course}: ${slide.label} (${slide.timestamp_seconds}s)`
          });
        }
      }
      window.triggerDigUpSlideClick = triggerDigUpSlideClick;

      // Global Keyboard Shortcuts
      window.addEventListener("keydown", e => {
        const ankiModal = document.getElementById("ankiModal");
        if (ankiModal && ankiModal.style.display !== "none") {
          const arena = document.getElementById("ankiStudyArena");
          const isStudying = (arena && arena.style.display !== "none");

          if (isStudying) {
            if (e.code === "Space" || e.key === "Enter") {
              e.preventDefault();
              if (!isCardFlipped) {
                flipCurrentCard();
              }
            } else if (e.key === "1") {
              gradeCurrentCard(1);
            } else if (e.key === "2") {
              gradeCurrentCard(2);
            } else if (e.key === "3") {
              gradeCurrentCard(3);
            } else if (e.key === "4") {
              gradeCurrentCard(4);
            } else if (e.key === "Escape") {
              exitAnkiStudyToDecks();
            }
          } else {
            if (e.key === "Escape") {
              closeAnkiModal();
            }
          }
        } else {
          // Check if Cornell modal is open
          const cornellModal = document.getElementById("cornellModal");
          if (cornellModal && cornellModal.style.display !== "none") {
            if (e.key === "Escape") {
              closeCornellModal();
              return;
            }
          }

          if (e.key === "Escape") {
            if (currentViewMode === "kanban") {
              setViewMode("constellation");
              return;
            }
          }

          // Toggle Kanban Board when pressing 'K' outside input fields
          
          // Toggle DigUp Multimodal Search Modal (Ctrl+Shift+Space or 'D')
          if ((e.code === "Space" && e.ctrlKey && e.shiftKey) || ((e.key === "d" || e.key === "D") && !e.ctrlKey && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName))) {
            e.preventDefault();
            const dModal = document.getElementById("digupModal");
            if (dModal && dModal.style.display !== "none") {
              closeDigUpModal();
            } else {
              openDigUpModal();
            }
            return;
          }

          if ((e.key === "k" || e.key === "K") && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
            e.preventDefault();
            setViewMode(currentViewMode === "kanban" ? "constellation" : "kanban");
          }
          // Toggle Anki Mode when pressing 'A' outside input fields
          else if ((e.key === "a" || e.key === "A") && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
            e.preventDefault();
            openAnkiModal();
          }
          // Toggle Cornell Notes Portal when pressing 'C' outside input fields
          else if ((e.key === "c" || e.key === "C") && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
            e.preventDefault();
            const modal = document.getElementById("cornellModal");
            if (modal && modal.style.display !== "none") {
              closeCornellModal();
            } else {
              openCornellModal("cornell_index.html", "Cornell Study Portal & Revision Notes");
            }
          }
        }
      });

